-- Additional catalogue products with dated prices and package sizes.

insert into public.products
  (name, brand, category, summary, region, data_notes, data_source,
   default_pao_months, price_usd, price_source, price_as_of,
   size_value, size_unit, size_source, image_url, image_source, sephora_url, ulta_url)
values
('Fit Me Matte + Poreless Foundation', 'Maybelline', 'foundation', 'The drugstore workhorse liquid foundation aimed at normal-to-oily skin: a lightweight, oil-free formula with a soft matte finish and a genuinely wide, well-loved shade range for the price. Coverage is light-to-medium and buildable, so don''t expect it to fully erase redness or dark spots on its own. The matte finish can read a touch flat or emphasize dry patches, so it rewards a good moisturizer underneath.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 11.99, 'brand', '2026-08-13', 30, 'ml', 'openbeautyfacts', 'https://www.maybelline.com/-/media/project/loreal/brand-sites/mny/americas/us/face-makeup/foundation/fit-me-matte-poreless-foundation/warm-sun/maybelline-fit-me-matte-poreless-334-warm-sun-041554539639-av11.jpg', 'other', null, 'https://www.ulta.com/p/fit-me-matte-poreless-liquid-foundation-xlsImpprod11861007'),
('True Match Super-Blendable Foundation', 'L''Oréal Paris', 'foundation', 'A longtime drugstore favorite built around a shade system sorted by warm/cool/neutral undertone, which makes finding a match easier than most in this price tier. It''s a medium-coverage liquid with a natural, skin-like finish - comfortable and unfussy rather than full-coverage or long-wear-heavy. If you want a matte or truly transfer-proof result you''ll likely want to set it, and very oily skin may find it slips as the day goes on.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 13.99, 'retailer', '2026-08-13', 30, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2602421?w=800', 'other', null, 'https://www.ulta.com/p/true-match-super-blendable-foundation-pimprod2034733'),
('Flawless Satin Foundation', 'e.l.f. Cosmetics', 'foundation', 'e.l.f.''s budget-hero liquid foundation, giving buildable medium coverage and a semi-matte ''satin'' finish for well under most competitors. Glycerin in the formula keeps it from looking parched, and it''s vegan and cruelty-free. The trade-offs are a smaller shade range than pricier lines and a slightly thinner texture that some find needs setting to last a full day.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 10, 'retailer', '2026-08-13', 20, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2554934?w=800', 'other', null, 'https://www.ulta.com/p/flawless-satin-foundation-xlsImpprod14541123'),
('Instant Age Rewind Eraser Concealer', 'Maybelline', 'concealer', 'The famous ''sponge-tip'' drugstore concealer that reviewers keep buying for under-eye brightening and general spot coverage. The cushiony applicator makes for quick, even blending, and coverage is medium and creamy. The flip side of that dispensing design is you can''t control exactly how much product loads onto the sponge, and it can crease on some without setting - so a light dusting of powder helps.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 12.99, 'retailer', '2026-08-13', 6, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2547762?w=800', 'other', null, 'https://www.ulta.com/p/instant-age-rewind-eraser-dark-circle-treatment-concealer-xlsImpprod3490149'),
('Revealer Concealer', 'Kosas', 'concealer', 'A ''skincare-makeup'' hybrid concealer that leans into a creamy, second-skin finish rather than heavy full coverage - the appeal is that it looks like skin and is comfortable enough for dry under-eyes. The brand highlights caffeine, hyaluronic acid, arnica and peptides in the formula; treat those as feel-good add-ons, not a substitute for actual eye cream or a measurable clinical claim. Coverage is medium and buildable, so deeper dark circles or blemishes may need a second layer or a more opaque concealer on top.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 32, 'brand', '2026-08-13', 6, 'ml', 'openbeautyfacts', 'https://kosas.com/cdn/shop/files/RC2024_01_vessel.jpg?width=800', 'other', 'https://www.sephora.com/product/kosas-revealer-concealer-P456151', null),
('Baked Blush', 'Milani', 'blush', 'A drugstore cult classic: a domed, marbled powder blush ''baked'' on terracotta that gives a soft, luminous, slightly radiant flush. Pigment is strong for the price, so a light hand on the first pass keeps it wearable, and the finish leans glowy rather than flat-matte. It''s powder, not cream, so very dry skin may want a hydrating base underneath.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 24, 12.99, 'retailer', '2026-08-13', 3.4, 'g', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2649942?w=800', 'other', null, 'https://www.ulta.com/p/baked-blush-pimprod2056506'),
('Benetint Cheek & Lip Stain', 'Benefit Cosmetics', 'blush', 'The original rose-tinted cheek and lip stain that basically invented the category back in the 70s. The sheer, buildable liquid dries down to a natural flush that stays put through the day, but the alcohol-based, wine-red formula takes a light hand and fast blending because it grabs fast and can go blotchy if you dawdle. Great for a your-cheeks-but-better wash of color; not the pick if you want opaque, powder-blush payoff.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 24, 30, 'retailer', '2026-08-17', 10, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2547730?w=800', 'other', 'https://www.sephora.com/product/benetint-cheek-lip-stain-P1272', 'https://www.ulta.com/p/benetint-liquid-lip-cheek-stain-pimprod2008308?sku=2547730'),
('Balm Dotcom', 'Glossier', 'lip', 'Glossier''s cult multipurpose balm, sold as a lip salve that doubles for cuticles and dry patches. It''s a comfortable, glossy, lightly-tinted-to-clear balm in a squeeze tube; pleasant and moisturizing but on the occlusive-glossy end rather than deeply treating. Note: it''s not a lip ''treatment'' with a hero active despite the branding, and the flavored versions carry fragrance, so pick Original/Unflavored if you''re sensitive.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 18, 16, 'brand', '2026-08-17', 15, 'ml', 'openbeautyfacts', 'https://glossier-prod.imgix.net/files/glossier-bdc-original-carousel-1.png?auto=compress,format&w=800', 'other', 'https://www.sephora.com/product/glossier-balm-dotcom-lip-balm-skin-salve-P512013', null),
('Beeswax Lip Balm', 'Burt''s Bees', 'lip', 'The drugstore classic in the yellow tube: a beeswax-and-peppermint balm that leaves a tingly, waxy, well-sealed finish. Dependable everyday lip protection at a couple of dollars, and it''s the benchmark most ''natural'' balms get compared to. Caveat: the peppermint oil gives that cooling tingle some people love and others find irritating on already-chapped lips, and it seals more than it deeply hydrates.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 18, 3.79, 'retailer', '2026-08-17', 4.25, 'g', 'openbeautyfacts', 'https://target.scene7.com/is/image/Target/GUEST_9e69daa0-7eff-40f4-992c-7c60b2ceef22?wid=800&hei=800&fmt=pjpeg', 'other', null, null),
('Toleriane Hydrating Gentle Cleanser', 'La Roche-Posay', 'cleanser', 'A milky, non-foaming cream cleanser aimed at dry and sensitive skin, formulated with ceramides and niacinamide and fragrance-free. It rinses clean without that tight, stripped feeling, which makes it a solid gentle daily wash for compromised or reactive barriers. Not for you if you want a squeaky, foamy lather or heavy-duty makeup removal — it''s deliberately low-key.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 21.99, 'retailer', '2026-08-17', 400, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2503387?w=800', 'other', null, 'https://www.ulta.com/p/toleriane-hydrating-gentle-face-cleanser-dry-skin-xlsImpprod15321285?sku=2503387'),
('Gentle Skin Cleanser', 'Cetaphil', 'cleanser', 'The ur-gentle cleanser dermatologists have recommended for decades: a soap-free, low-lather, fragrance-free wash for the face and body that you can even wipe off without water. It''s genuinely non-stripping and about as unlikely to irritate as cleansers get, which is exactly the point. The flip side is it''s a bare-minimum cleanser — it won''t exfoliate, treat, or fully cut heavy sunscreen and makeup on its own.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 12.89, 'retailer', '2026-08-17', 473, 'ml', 'openbeautyfacts', 'https://target.scene7.com/is/image/Target/GUEST_416641c9-3ed2-4c7b-80b9-358cd224dc08?wid=800&hei=800&fmt=pjpeg', 'other', null, null),
('PM Facial Moisturizing Lotion', 'CeraVe', 'moisturizer', 'A lightweight, oil-free night lotion built around ceramides, niacinamide and hyaluronic acid, and it''s fragrance-free. It layers well and absorbs fast, making it a reliable, affordable barrier-supporting moisturizer for most skin types including oilier ones. Despite the ''PM'' name it has no actives that require darkness, so you can wear it AM too; just know it''s a thin lotion, not a rich cream for very dry winter skin.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 14.99, 'retailer', '2026-08-17', 89, 'ml', 'openbeautyfacts', 'https://target.scene7.com/is/image/Target/GUEST_8993af54-6376-4d1e-9efb-168e260a92ce?wid=800&hei=800&fmt=pjpeg', 'other', null, 'https://www.ulta.com/p/pm-facial-moisturizing-lotion-xlsImpprod5140067?sku=2254422'),
('Toleriane Double Repair Face Moisturizer', 'La Roche-Posay', 'moisturizer', 'A no-drama daily face cream built on ceramides, niacinamide, and glycerin, with La Roche-Posay''s thermal spring water for a soothing angle. It''s a reliable barrier-repair moisturizer that plays nicely under other actives and won''t feel greasy. Fragrance-free and dermatologist-favored, but this is the non-SPF version, so it does nothing for sun protection on its own.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 25.99, 'retailer', '2026-08-17', 100, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2509730?w=800', 'other', null, 'https://www.ulta.com/p/toleriane-double-repair-face-moisturizer-with-niacinamide-xlsImpprod16011007?sku=2509730'),
('Moisture Surge 100H Auto-Replenishing Hydrator', 'Clinique', 'moisturizer', 'Clinique''s cult oil-free gel-cream, leaning on hyaluronic acid and aloe bioferment for lightweight, refreshing hydration that suits most skin types. The ''100H'' name refers to Clinique''s own claim of long-lasting hydration, not an independently verified spec, so take the hour count as marketing. It''s genuinely comfortable and fragrance-free, but at this price you''re paying a premium for a gel that mainly hydrates rather than repairs or treats.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 48, 'retailer', '2026-08-17', 50, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2576545?w=800', 'other', 'https://www.sephora.com/product/clinique-moisture-surge-trade-100-hour-auto-replenishing-hydrator-P468351', 'https://www.ulta.com/p/moisture-surge-100h-auto-replenishing-hydrator-gel-moisturizer-with-hyaluronic-acid-pimprod2021615?sku=2576545'),
('Hyaluronic Acid Serum', 'The INKEY List', 'serum', 'A budget-friendly hydrating serum built around multi-molecular hyaluronic acid, with a peptide (Matrixyl 3000) along for the ride. Great value for plumping surface hydration and layering under moisturizer. Just remember HA draws water in, so in very dry air seal it with a cream or it can pull moisture the wrong way.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 6, 13, 'brand', '2026-08-17', 30, 'ml', 'openbeautyfacts', 'https://www.theinkeylist.com/cdn/shop/files/Hyaluronic_Acid_Hero_Allure_2000x2000_b7e7a05c-40fc-466d-bf9a-3a7c5d587b7a_300x.jpg?v=1749041477', 'other', 'https://www.sephora.com/product/hyaluronic-acid-hydrating-face-serum-P443845', null),
('10% Niacinamide Booster', 'Paula''s Choice', 'serum', 'A concentrated niacinamide booster you can use solo or mix a few drops into your moisturizer, aimed at the look of enlarged pores, uneven tone, and texture. 10% is on the higher end of niacinamide concentrations, which is effective for most but can be more than sensitive skin wants, so start slow. Fragrance-free and well-formulated, though it''s a small 20 ml bottle for the price.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 6, 53, 'brand', '2026-08-17', 20, 'ml', 'openbeautyfacts', 'https://static.thcdn.com/productimg/original/11316245-1435306476078095.jpg', 'other', 'https://www.sephora.com/product/paulas-choice-10-niacinamide-booster-P480628', null),
('Vitamin C Complex Serum', 'Naturium', 'serum', 'A gentle, affordable vitamin C serum that uses a complex of vitamin C forms rather than straight L-ascorbic acid, so it''s easier to tolerate than the notoriously finicky pure-acid formulas. Good for gradually brightening and evening tone without the sting some C serums bring. The tradeoff is that these milder derivatives are generally less potent than well-formulated L-ascorbic acid, so results are subtle and slow.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 6, 21, 'brand', '2026-08-17', 30, 'ml', 'openbeautyfacts', 'https://naturium.com/cdn/shop/files/NATR_VitaminC_ComplexSerum_brighter_Front_CapOn_2_ecomm.webp?width=800', 'other', null, 'https://www.ulta.com/p/vitamin-c-complex-serum-pimprod2045642?sku=2627280'),
('Minéral 89 Hyaluronic Acid Face Serum', 'Vichy', 'serum', 'A lightweight, watery daily hydrating booster combining hyaluronic acid with Vichy''s mineral-rich volcanic water. It absorbs fast, layers well, and is a solid first-step hydrator for most skin types. Don''t expect anti-aging heavy lifting though, this is essentially a well-made hydration serum, not a treatment for wrinkles or dark spots.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 6, 29.99, 'retailer', '2026-08-17', 50, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2512460?w=800', 'other', null, 'https://www.ulta.com/p/mineral-89-hyaluronic-acid-face-serum-stronger-skin-pimprod2004930?sku=2512460'),
('Hydrating Mineral Sunscreen SPF 30', 'CeraVe', 'sunscreen', 'CeraVe''s 100% mineral (zinc oxide + titanium dioxide) face sunscreen for sensitive skin, fragrance-free and folded into a hydrating lotion base with ceramides, hyaluronic acid and niacinamide. A solid everyday SPF 30 if chemical filters bother you. Honest caveat: mineral formulas like this can leave a slight white or greyish cast, especially on deeper skin tones, and the untinted version is the one prone to it.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 13.99, 'retailer', '2026-08-13', 73.9, 'ml', 'openbeautyfacts', 'https://target.scene7.com/is/image/Target/GUEST_c722ef2d-2e03-41b1-8f8a-789a92799deb?wid=800&hei=800&fmt=pjpeg', 'other', null, null),
('Make It Matte SPF 45', 'Black Girl Sunscreen', 'sunscreen', 'Make It Matte is Black Girl Sunscreen''s oily/combination-skin sunscreen: a lightweight SPF 45 gel that dries down matte with no white cast on deeper skin tones — which is the whole reason the brand exists. It''s a chemical formula, so it still needs the usual generous, even reapplication to actually deliver the SPF on the label.', 'US', 'SPF value appears in the product name. Chemical UV filters and percentages appear on the drug-facts label; not yet ingested from a verified source.', 'seed', 12, 19.99, 'retailer', '2026-08-13', 89, 'ml', 'retailer', null, null, null, 'https://www.ulta.com/p/make-it-matte-sunscreen-spf-45-pimprod2030390?sku=2592310'),
('Witch Hazel Facial Toner', 'Thayers', 'toner', 'The drugstore-classic alcohol-free witch hazel toner, built on witch hazel plus aloe vera for a gentle, non-stripping swipe after cleansing. Reliable, cheap and widely loved for calming and light hydration rather than any active exfoliation. Note: it comes in several versions (Original/scented, Rose Petal, Lavender, Unscented) so check which one you''re grabbing if fragrance is a concern.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 10.99, 'retailer', '2026-08-13', 355, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2548485?w=800', 'other', null, 'https://www.ulta.com/p/alcohol-free-witch-hazel-facial-toner-pimprod2006476?sku=2548485'),
('AHA 30% + BHA 2% Peeling Solution', 'The Ordinary', 'exfoliant', 'The Ordinary''s cult ''blood mask'' — a high-strength 30% AHA + 2% BHA rinse-off peel (both concentrations are right in the name) for a periodic reset on dull, uneven texture. It works, but it''s genuinely strong: leave on no more than 10 minutes, use at most once or twice a week, and never skip sunscreen after. Not for sensitive, compromised, or actively broken-out skin, and not a daily product.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 9.5, 'brand', '2026-08-13', 30, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2551153?w=800', 'other', 'https://www.sephora.com/product/aha-30-bha-2-peeling-solution-P442563', 'https://www.ulta.com/p/aha-30-bha-2-high-strength-peeling-solution-brightening-pimprod2007102?sku=2551153'),
('Retinol 0.5% in Squalane', 'The Ordinary', 'treatment', 'A water-free 0.5% pure retinol (the concentration is in the name) suspended in squalane, positioned as the middle rung of The Ordinary''s retinol ladder for texture and early signs of aging. The squalane base makes it more cushioned than their retinoid emulsions, but 0.5% pure retinol is still potent — expect possible dryness or flaking and build up slowly. Start a couple of nights a week, and it''s an evening-only product that demands daytime SPF.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 6, 9.3, 'brand', '2026-08-13', 30, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2551172?w=800', 'other', null, 'https://www.ulta.com/p/retinol-05-in-squalane-intermediate-retinol-serum-pimprod2007127?sku=2551172'),
('Eye Repair Cream', 'CeraVe', 'eye_cream', 'A no-frills, fragrance-free under-eye cream with ceramides, hyaluronic acid, niacinamide and a marine/plant complex, marketed to soften the look of dark circles and puffiness. It''s a dependable, gentle hydrator that reinforces the skin barrier at a drugstore price. Honest limit: it won''t erase true dark circles or structural puffiness — think comfortable moisture and a smoother base, not a dramatic before/after.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 6, 19.99, 'retailer', '2026-08-13', 14, 'ml', 'openbeautyfacts', 'https://media.ulta.com/i/ulta/2269490?w=800', 'other', null, 'https://www.ulta.com/p/eye-repair-cream-dark-circles-puffy-under-eyes-xlsImpprod6480077?sku=2269490'),
('Facial Spray with Aloe, Herbs and Rosewater', 'Mario Badescu', 'mist', 'A cult-favorite drugstore-price face mist of rosewater, aloe, and herb extracts meant for a quick hit of refreshment mid-day or a dewy finish over makeup. It feels lovely and smells like roses, but be honest about what it is: mostly a pleasant hydrating spritz, not a treatment. It won''t deeply moisturize on its own (water evaporates, so seal it with a moisturizer), and the rose fragrance can bother very sensitive or reactive skin.', 'US', 'Formulas can change over time and by market; full ingredient list not yet ingested from a verified source.', 'seed', 12, 14, 'brand', '2026-08-17', 118, 'ml', 'openbeautyfacts', 'https://www.mariobadescu.com/cdn/shop/files/FacialSpraywithAloeHerbsandWater-2oz-785364130319-1-PLP-White-4000x4000_300dpi.jpg?width=800', 'other', null, 'https://www.ulta.com/p/facial-spray-with-aloe-herbs-rosewater-xlsImpprod6200727?sku=2209889')
on conflict (brand, name) do nothing;
